## Summary
Implement the `Runtime<Rnn>` trait for `HipRuntime`, enabling it to be used as a drop-in replacement for WGPU runtime.

## Context
This is the main deliverable - making HIP work with existing web-rwkv examples and server code.

## Implementation
**File:** `src/hip/runtime.rs`

```rust
use futures::future::BoxFuture;
use crate::runtime::{
    infer::{Rnn, RnnChunk, RnnInfo, RnnInput, RnnOutput, RnnOutputBatch, RnnRedirect},
    Runtime, RuntimeError,
};

impl HipRuntime {
    fn infer_impl(&self, mut input: RnnInput) -> Result<(RnnInput, RnnOutput), RuntimeError> {
        // Get chunk info
        let Some(info) = input.iter().next() else {
            return Err(RuntimeError::InputExhausted);
        };
        let chunk = input.chunk();
        let redirect = info.redirect();

        // Handle empty chunk
        if chunk.num_token() == 0 {
            let empty_outputs = self.create_empty_outputs(chunk.num_batch());
            input.step();
            return Ok((input, RnnOutput(empty_outputs)));
        }

        // Pad sequences to equal length
        let (padded_tokens, lengths) = self.pad_sequences(&chunk);
        let padded_len = padded_tokens[0].len();
        let token_refs: Vec<&[u32]> = padded_tokens.iter().map(|v| v.as_slice()).collect();

        // Run forward pass with mutex-guarded state
        let logits = {
            let mut state = self.state.lock().map_err(|_| {
                RuntimeError::TensorError(TensorError::Deduplicate)
            })?;
            self.model
                .forward_with_state_masked(&token_refs, &lengths, &mut state)
                .map_err(|e| RuntimeError::TensorError(e.into()))?
        };

        // Extract outputs based on redirect
        let output = self.extract_outputs(&logits, &info, &redirect, padded_len, &lengths)?;

        input.step();
        Ok((input, output))
    }
}

impl Runtime<Rnn> for HipRuntime {
    fn infer(&self, input: RnnInput) -> BoxFuture<'_, Result<(RnnInput, RnnOutput), RuntimeError>> {
        Box::pin(async move { self.infer_impl(input) })
    }
}
```

